const config=window.CAMPUS_CONFIG||{};
let items=window.STARTER_ITEMS, category='all', savedOnly=false;
let saved;try{saved=new Set(JSON.parse(localStorage.getItem('campus-saved')||'[]'))}catch{saved=new Set()}
const $=s=>document.querySelector(s);
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeUrl(s){try{const u=new URL(s);return u.protocol==='https:'?u.href:'#'}catch{return '#'}}
function visibleItems(){const q=$('#search').value.trim().toLowerCase(),loc=$('#location').value;let result=items.filter(i=>(category==='all'||i.category===category)&&(!savedOnly||saved.has(i.id))&&(loc==='all'||i.location===loc)&&[i.title,i.organization,i.summary,...(i.tags||[])].join(' ').toLowerCase().includes(q));const sort=$('#sort').value;if(sort==='latest')result.sort((a,b)=>(Date.parse(b.published_at)||0)-(Date.parse(a.published_at)||0));if(sort==='popular')result.sort((a,b)=>(b.popularity||0)-(a.popularity||0));return result}
function render(){const result=visibleItems();$('#result-count').textContent=`${result.length} ${savedOnly?'saved resources':'resources to explore'}`;$('#saved-count').textContent=saved.size;$('#empty').hidden=!!result.length;$('#cards').innerHTML=result.map(i=>`<article class="card"><div class="card-top"><span class="logo" aria-hidden="true">${escapeHtml(i.symbol||'↗')}</span><button class="save" data-save="${escapeHtml(i.id)}" aria-label="${saved.has(i.id)?'Unsave':'Save'} ${escapeHtml(i.title)}" aria-pressed="${saved.has(i.id)}">${saved.has(i.id)?'♥':'♡'}</button></div><div class="category">${escapeHtml(i.category)} · ${escapeHtml(i.organization)}</div><h3><button data-detail="${escapeHtml(i.id)}">${escapeHtml(i.title)}</button></h3><p>${escapeHtml(i.summary)}</p><div class="card-meta"><span class="pill">${escapeHtml(i.location||'Unknown location')}</span>${(i.tags||[]).slice(0,2).map(t=>`<span class="pill">${escapeHtml(t)}</span>`).join('')}</div><div class="card-bottom"><span>${i.verified_at?'Checked '+escapeHtml(new Date(i.verified_at).toLocaleDateString()):'Official resource · check source'}</span><a href="${escapeHtml(safeUrl(i.source_url))}" target="_blank" rel="noopener noreferrer" aria-label="Visit ${escapeHtml(i.organization)}">Visit source ↗</a></div></article>`).join('');document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',!savedOnly&&b.dataset.tab===category));$('#saved-nav').setAttribute('aria-pressed',savedOnly)}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){category=tab.dataset.tab;savedOnly=false;render();if(tab.closest('nav')||tab.closest('aside'))$('#discover').scrollIntoView({behavior:'smooth'});}const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('campus-saved',JSON.stringify([...saved]))}catch{}render()}const detail=e.target.closest('[data-detail]');if(detail){const i=items.find(x=>x.id===detail.dataset.detail);$('#detail-content').innerHTML=`<p class="eyebrow">${escapeHtml(i.category)}</p><h2>${escapeHtml(i.title)}</h2><p>${escapeHtml(i.organization)} · ${escapeHtml(i.location)}</p><p>${escapeHtml(i.summary)}</p><p>Eligibility and current availability: verify with the original provider.</p><a class="primary" target="_blank" rel="noopener noreferrer" href="${escapeHtml(safeUrl(i.source_url))}">Visit original source ↗</a>`;$('#detail').showModal()}});
$('#saved-nav').onclick=()=>{savedOnly=!savedOnly;render();$('#discover').scrollIntoView({behavior:'smooth'})};$('#close-detail').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};$('#search').oninput=render;$('#location').onchange=render;$('#sort').onchange=render;$('#clear').onclick=()=>{category='all';savedOnly=false;$('#search').value='';$('#location').value='all';$('#sort').value='editor';render()};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}});
async function load(){render();if(!config.supabaseUrl||!config.publishableKey){$('#sort option[value=popular]').disabled=true;$('#sort option[value=popular]').textContent='Popularity available with live data';return}try{const response=await fetch(config.supabaseUrl.replace(/\/$/,'')+'/rest/v1/listings?select=*&status=eq.published&order=published_at.desc&limit=200',{headers:{apikey:config.publishableKey}});if(!response.ok)throw Error('Database request failed');items=await response.json();$('#mode').textContent='Live directory · checked at source';render()}catch{$('#mode').textContent='Live directory unavailable · showing starter resources';}}load();
